head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[selectbox > P > keyMoveListSync]<br/>펼쳐진 아이템 리스트에서 키보드로 아이템을 이동할때 선택 처리를 동시에 할지 설정합니다.",
    "validation" : [        
        "renderType=component 이고, 아이템이 ItemSet 또는 BindItemSet 으로 정의된 경우에 동작합니다.",
        "미설정 시 아이템 리스트에서 아이템 이동이 완료된 후 Enter, 클릭 등의 액션으로 선택 처리됩니다.",
        "true 설정 시 아이템 리스트에서 아이템 이동 시 선택 처리됩니다.",
        "true 설정 시 컴포넌트의 아이템 표시 영역에 선택된 아이템의 라벨값이 표시되고, onviewchange 이벤트가 발생합니다.",
        "false 설정 시 아이템 리스트에서 아이템 이동이 완료된 후 Enter, 클릭 등의 액션으로 선택 처리됩니다.",
        "미설정 또는 false 설정 시 아이템 리스트창이 닫힐때 onviewchange 이벤트가 발생합니다.",
        "아이템 선택이 완료되고 아이템 리스트창이 닫힐때 onselected 이벤트는 항상 발생합니다.",        
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {        
        keyMoveListSync : con_keyMoveListSync.getText(),
    }

    let cList = $c.gcm.createCList(properties)
    let eList = $c.gcm.createEList(["onviewchange", "onselected"]);

    // target 생성    
    $c.gcm.createBasicSelectBox(cList, eList);
}



scwin.target1_onviewchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("getText : " + target1.getText());
}



scwin.target1_onselected = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onselected=====");
}
